@Test
  public void testRelativePathWindows()
    {
    String path = "..\\some\\directory";
    URISanitizer sanitizer = new URISanitizer();
    String result = sanitizer.apply( Visibility.PRIVATE, path );
    assertEquals( "../some/directory", result );
    }

